<p class="eyebrow">Deposit request</p><h1><?= e($deposit['reference']) ?></h1><section class="card"><dl class="detail-list"><dt>Status</dt><dd><?= e($deposit['status']) ?></dd><dt>Requested</dt><dd><?= money((int)$deposit['requested_amount_minor']) ?></dd><dt>Expected credit</dt><dd><?= money((int)$deposit['expected_credit_minor']) ?></dd><?php if($deposit['rejection_reason']): ?><dt>Reason</dt><dd><?= e($deposit['rejection_reason']) ?></dd><?php endif; ?></dl><?php if($deposit['status']==='PENDING'): ?><form method="post" action="<?= e(route('dashboard.deposit.cancel',['deposit'=>$deposit['reference']])) ?>"><?= app('csrf')->input() ?><button class="button button-secondary">Cancel request</button></form><?php endif; ?></section><section class="card"><h2>Submitted details</h2><?php foreach($values as $value): ?><p><strong><?= e($value['field_label']) ?>:</strong> <?= e($value['value_text']) ?></p><?php endforeach; ?><h2>Uploaded proof</h2><?php foreach($files as $file): ?><p><a href="<?= e(route('dashboard.deposit.file',['deposit'=>$deposit['reference'],'file'=>$file['id']])) ?>"><?= e($file['original_filename']) ?></a></p><?php endforeach; ?></section>
